          "title": "User Id"
        },
        "vehicle_id": {
          "type": "integer",
          "title": "Vehicle Id"
        },
        "service_id": {
          "type": "integer",
          "title": "Service Id"
        },
        "service_package_id": {
          "anyOf": [
            {
